// Le bandiere EN/ES riusano le immagini italiane cambiando solo il testo alternativo
(function(){[QUIZ_DATA_EN,QUIZ_DATA_ES].forEach(function(t){for(var g in t){t[g].questions.forEach(function(q,i){if(q.q&&q.q.flagAlt!==undefined){var a=String(q.q.flagAlt).replace(/"/g,"&quot;");q.q=QUIZ_DATA[g].questions[i].q.replace(/alt="[^"]*"/,"alt=\""+a+"\"");}});}});})();
// Quiz della lingua attiva (ricade sull'italiano)
function quizDataFor(name){var t=(typeof LANG!=="undefined"&&LANG==="en")?QUIZ_DATA_EN:(typeof LANG!=="undefined"&&LANG==="es")?QUIZ_DATA_ES:QUIZ_DATA;return t[name]||QUIZ_DATA[name];}
